target.css:
:root {
  --cover: #3b2f1e;
  --cover-light: #5a4230;
  --cream: #f4ead5;
  --ink: #2b1f0f;
  --ink-mid: #6b4f2a;
  --ink-faint: #a88a5e;
  --rule: #c9aa76;
  --stamp: #8b2e1a;
  --stamp-border: #c04530;
  --white: #fffdf7;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
}

.notebook {
  background-color: var(--cover);
  width: 420px;
  border-radius: 4px 10px 10px 4px;
  border-left: 14px solid var(--cover-light);
  padding: 0;
  overflow: hidden;
}

.nb-header {
  background-color: var(--cream);
  padding: 14px 20px 10px;
  border-bottom: 3px double var(--rule);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nb-series {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--ink-faint);
  text-transform: uppercase;
}

.nb-title {
  font-size: 26px;
  font-weight: 800;
  color: var(--ink);
  margin: 0;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.nb-subtitle {
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-mid);
  margin: 0;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.nb-body {
  background-color: var(--cream);
  padding: 12px 20px 10px;
  border-bottom: 2px solid var(--rule);
}

.nb-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.nb-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background-color: var(--white);
  border: 1px solid var(--rule);
  border-radius: 3px;
  padding: 6px 8px;
}

.cell-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--ink-faint);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.cell-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
}

.nb-divider {
  height: 1px;
  background-color: var(--rule);
  margin: 10px 0;
  opacity: 0.6;
}

.nb-contents {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nb-contents li {
  font-size: 12px;
  color: var(--ink-mid);
  display: flex;
  align-items: center;
  gap: 7px;
  letter-spacing: 0.02em;
}

.dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--ink-faint);
  flex-shrink: 0;
}

.nb-footer {
  background-color: var(--cover-light);
  padding: 9px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nb-stamp {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--stamp-border);
  border: 2px solid var(--stamp-border);
  padding: 3px 7px;
  border-radius: 2px;
  text-transform: uppercase;
}

.nb-publisher {
  font-size: 10px;
  color: var(--cream);
  letter-spacing: 0.06em;
  opacity: 0.8;
}

